  popup_report_sent: { en: "Reported, thanks. It will be reviewed.", tr: "Bildirildi, teşekkürler. İncelenecek.", de: "Gemeldet, danke. Wird geprüft.", es: "Enviado, gracias. Será revisado.", fr: "Signalé, merci. Ce sera vérifié.", pt_BR: "Enviado, obrigado. Será analisado.", ru: "Отправлено, спасибо. Будет проверено.", hi: "रिपोर्ट भेजी गई, धन्यवाद। समीक्षा होगी।", zh_CN: "已举报，谢谢。将进行审核。", ja: "報告しました。確認されます。", ko: "신고됨, 감사합니다. 검토됩니다.", vi: "Đã báo cáo, cảm ơn. Sẽ được xem xét.", id: "Dilaporkan, terima kasih. Akan ditinjau." },
